import React, { useEffect, useRef, useState } from 'react';
import { Alert, Badge, Spinner } from 'react-bootstrap';
import ModelViewBox from '../../components/Atom/ModelViewBox';
import FormLayout from '../../utils/formLayout';
import { settingDeductionContainer } from './formFieldData';
import Table from '../../components/Table';
import { dateConversion, findArrObj, showConfirmationDialog, showMessage } from '../../utils/AllFunction';
import {
    createSettingDeductionRequest,
    getActivityRequest,
    getSettingDeductionRequest,
    resetCreateSettingDeduction,
    resetGetActivity,
    resetGetSettingDeduction,
    resetUpdateSettingDeduction,
    updateSettingDeductionRequest,
} from '../../redux/actions';
import { usePageTitle, useRedux } from '../../hooks';
import { NotificationContainer } from 'react-notifications';
import _ from 'lodash';

let isEdit = false;

function Index() {


    usePageTitle({
        title: 'Settings',
        breadCrumbItems: [
            {
                path: '/settings/salary-doa',
                label: 'Settings',
            },
            {
                path: '/settings/salary-doa',
                label: 'Salary DOA',
                active: true,
            },
        ],
    });

    const { dispatch, appSelector } = useRedux();
    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData?.[0]?.pagePermission, 'label', "Setting");
    const accessIds = (pageAccessData?.[0]?.children?.[1]?.access || '').split(',').map(id => id.trim()); // for access create and update and delete actions ['1', '2', '3', '4', '5', '6']
    const branchIdforRole = localData?.[0]?.branchId; // for branch list can only show
    const roleIdforRole = localData?.[0]?.roleId; // for role Permission (1.superadmin)

    const {
        getSettingDeductionSuccess,
        getSettingDeductionList,
        getSettingDeductionFailure,
        getActivitySuccess,
        getActivityList,
        getActivityFailure,
        createSettingDeductionSuccess,
        createSettingDeductionData,
        createSettingDeductionFailure,
        updateSettingDeductionSuccess,
        updateSettingDeductionData,
        updateSettingDeductionFailure,
        errorMessage,
    } = appSelector((state) => ({
        getSettingDeductionSuccess: state.settingDeductionReducer.getSettingDeductionSuccess,
        getSettingDeductionList: state.settingDeductionReducer.getSettingDeductionList,
        getSettingDeductionFailure: state.settingDeductionReducer.getSettingDeductionFailure,

        getActivitySuccess: state.activityReducer.getActivitySuccess,
        getActivityList: state.activityReducer.getActivityList,
        getActivityFailure: state.activityReducer.getActivityFailure,

        createSettingDeductionSuccess: state.settingDeductionReducer.createSettingDeductionSuccess,
        createSettingDeductionData: state.settingDeductionReducer.createSettingDeductionData,
        createSettingDeductionFailure: state.settingDeductionReducer.createSettingDeductionFailure,

        updateSettingDeductionSuccess: state.settingDeductionReducer.updateSettingDeductionSuccess,
        updateSettingDeductionData: state.settingDeductionReducer.updateSettingDeductionData,
        updateSettingDeductionFailure: state.settingDeductionReducer.updateSettingDeductionFailure,

        errorMessage: state.settingDeductionReducer.errorMessage,
    }));

    const columns = [
        {
            Header: 'S.No',
            accessor: 'id',
            Cell: (row) => <div>{row?.row?.index + 1}</div>,
        },
        {
            Header: 'Name',
            accessor: 'deductionName',
            sort: true,
        },
        {
            Header: 'Value',
            accessor: 'deductionValue',
            Cell: ({ row }) => <div>{`${row?.original?.isPercentage ? '' : '₹ '}${row?.original?.deductionValue}${row?.original?.isPercentage ? ' %' : ''}`}</div>
        },
        {
            Header: 'Is this a Increment or a Including?',
            accessor: 'isIncrementName',
            sort: true,
        },
        {
            Header: 'Is this a deduction or allowance?',
            accessor: 'isDeductionName',
            Cell: ({ row }) => <div className={`${row?.original?.isDeduction ? 'text-danger' : 'text-success'}`}>{row?.original?.isDeductionName}</div>,
        },
        {
            Header: 'Actions',
            accessor: 'actions',
            Cell: ({ row }) => {
                const activeChecker = row.original.isActive;
                const iconColor = activeChecker ? 'text-danger' : 'text-warning';
                const deleteMessage = activeChecker ? 'You want to In-Active...?' : 'You want to retrive this Data...?';
                return (
                    <div>
                        {(roleIdforRole == 1 || _.includes(accessIds, '2')) &&
                            <span
                                className="text-success  me-2 cursor-pointer"
                                onClick={() => onEditForm(row.original, row.index)}>
                                <i className={'fe-edit-1'}></i>
                            </span>}
                        {
                            (roleIdforRole == 1 || _.includes(accessIds, '3')) &&
                            <span
                                className={`${iconColor} cursor-pointer`}
                                onClick={() =>
                                    showConfirmationDialog(
                                        deleteMessage,
                                        () => onDeleteForm(row.original, row.index, activeChecker),
                                        'Yes'
                                    )
                                }>
                                {
                                    row?.original?.isActive ? <i className={'fe-trash-2'}></i> : <i className={'fas fa-recycle'}></i>
                                }
                            </span>
                        }
                    </div>
                );
            },
        },
    ];

    const [state, setState] = useState({
        isPercentage: 1,
        isDeduction: 1,
        isIncrement: 0,
    });
    const [parentList, setParentList] = useState([]);
    const [optionListState, setOptionListState] = useState({
        percentageList: [
            {
                isPercentage: 1,
                isPercentageName: 'Percentage',
            },
            {
                isPercentage: 0,
                isPercentageName: 'Amount',
            },
        ],
        deductionList: [
            {
                isDeduction: 1,
                isDeductionName: 'Deduction',
            },
            {
                isDeduction: 0,
                isDeductionName: 'Allowance',
            },
        ],
        incrementList: [
            {
                isIncrement: 0,
                isIncrementName: 'Including',
            },
            {
                isIncrement: 1,
                isIncrementName: 'Increment',
            },
        ],
    });
    const [selectedItem, setSelectedItem] = useState({});
    const [selectedIndex, setSelectedIndex] = useState(false);
    const [modal, setModal] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [errors, setErrors] = useState([]);
    const [showAlert, setShowAlert] = useState(true);

    const handleClose = () => {
        setShowAlert(false);
    };


    const errorHandle = useRef();

    useEffect(() => {
        setIsLoading(true);
        dispatch(getSettingDeductionRequest());
    }, []);

    useEffect(() => {
        if (getSettingDeductionSuccess) {
            setIsLoading(false);
            setParentList(getSettingDeductionList);
            dispatch(resetGetSettingDeduction());
        } else if (getSettingDeductionFailure) {
            setIsLoading(false);
            setParentList([]);
            dispatch(resetGetSettingDeduction());
        }
    }, [getSettingDeductionSuccess, getSettingDeductionFailure]);

    useEffect(() => {
        if (createSettingDeductionSuccess) {
            const temp_state = [createSettingDeductionData[0], ...parentList];
            setParentList(temp_state);
            showMessage('success', 'Created Successfully');
            closeModel();
            dispatch(resetCreateSettingDeduction());
        } else if (createSettingDeductionFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetCreateSettingDeduction());
        }
    }, [createSettingDeductionSuccess, createSettingDeductionFailure]);

    useEffect(() => {
        if (updateSettingDeductionSuccess) {
            const temp_state = [...parentList];
            temp_state[selectedIndex] = updateSettingDeductionData[0];
            setParentList(temp_state);
            isEdit && showMessage('success', 'Updated Successfully');
            closeModel();
            dispatch(resetUpdateSettingDeduction());
        } else if (updateSettingDeductionFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetUpdateSettingDeduction());
        }
    }, [updateSettingDeductionSuccess, updateSettingDeductionFailure]);

    const closeModel = () => {
        isEdit = false;
        onFormClear();
        setModal(false);
    };

    const onFormClear = () => {
        setState({
            ...state,
            isPercentage: 1,
            isDeduction: 1,
            isIncrement: 0,
            deductionName: '',
            deductionValue: '',
        });
    };

    const createModel = () => {
        onFormClear();
        isEdit = false;
        setModal(true);
    };

    const onEditForm = (data, index) => {
        setState({
            ...state,
            isPercentage: data?.isPercentage || 0,
            isDeduction: data?.isDeduction || 0,
            isIncrement: data?.isIncrement || 0,
            deductionName: data?.deductionName || '',
            deductionValue: data?.deductionValue || '',
        });
        isEdit = true;
        setSelectedItem(data);
        setSelectedIndex(index);
        setModal(true);
    };

    const onDeleteForm = (data, index, activeChecker) => {
        const submitRequest = {
            isActive: activeChecker == 0 ? 1 : 0
        }
        setSelectedIndex(index)
        dispatch(updateSettingDeductionRequest(submitRequest, data.settingDeductionId))
    };

    const handleValidation = () => {
        errorHandle.current.validateFormFields();
    };

    const onFormSubmit = async () => {
        const submitRequest = {
            isPercentage: state?.isPercentage || 0,
            isDeduction: state?.isDeduction || 0,
            isIncrement: state?.isIncrement || 0,
            deductionName: state?.deductionName || '',
            deductionValue: state?.deductionValue || '',
        };
        if (isEdit) {
            dispatch(updateSettingDeductionRequest(submitRequest, selectedItem.settingDeductionId));
        } else {
            dispatch(createSettingDeductionRequest(submitRequest));
        }
    };

    return (
        <React.Fragment>
            <NotificationContainer />
            {isLoading ? (
                <div className="bg-light opacity-0.25">
                    <div className="d-flex justify-content-center m-5">
                        <Spinner className="mt-5 mb-5" animation="border" />
                    </div>
                </div>
            ) : (
                <>
                    {showAlert && (
                        <Alert variant="info" onClose={handleClose} dismissible>
                            <strong>Note:</strong> PF is assigned to index 1 and ESI to index 2. Kindly avoid modifying their names; you may update their values if necessary.
                            <br />
                            For any additional deductions or allowances, please use indexes greater than 2.
                        </Alert>
                    )}

                    <Table
                        columns={columns}
                        Title={'Salary Deduction Or Allowance List'}
                        data={parentList || []}
                        pageSize={25}
                        toggle={createModel}
                    /></>
            )}

            <ModelViewBox
                modal={modal}
                setModel={setModal}
                modelHeader={'Deduction Or Allowance'}
                modelSize={'md'}
                isEdit={isEdit}
                handleSubmit={handleValidation}>
                <FormLayout
                    dynamicForm={settingDeductionContainer}
                    handleSubmit={onFormSubmit}
                    optionListState={optionListState}
                    setState={setState}
                    state={state}
                    ref={errorHandle}
                    noOfColumns={1}
                    errors={errors}
                    setErrors={setErrors}
                />
            </ModelViewBox>
        </React.Fragment>
    );
}

export default Index;
